87:       ? `Você levou os ${score} patches até o destino. Rua é movimento!`
88:       : score >= 12
89:         ? 'Você pegou todos os patches! Tente fazer a entrega sem perder as vidas.'
90:         : `Você levou ${score} de 12 patches. Respira e tenta mais uma vez.`;
91:     startButton.innerHTML = 'JOGAR DE NOVO <span>↗</span>';
92:     gameOverlay.classList.remove('is-hidden');
93:     updateHud();
94:   }
