96:   function jump() {
97:     if (state === 'playing' && player.onGround) {
98:       player.vy = -690;
99:       player.onGround = false;
100:     }
101:   }
102: 
103:   function overlaps(a, b) {
104:     return a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y;
105:   }
106: 
107:   function update(dt) {
108:     scenery += dt * (state === 'playing' ? 230 + elapsed * 2.2 : 35);
109:     if (state !== 'playing') return;
110: 
111:     elapsed += dt;
112:     if (Math.ceil(60 - elapsed) !== displayedTime) updateHud();
113:     invulnerable = Math.max(0, invulnerable - dt);
114:     const direction = Number(held.right) - Number(held.left);
115:     player.x = Math.max(28, Math.min(W - player.width - 28, player.x + direction * 360 * dt));
116:     player.leg += dt * (direction ? 17 : 8);
117:     player.vy += 1850 * dt;
118:     player.y += player.vy * dt;
119:     if (player.y >= ground - player.height) {
120:       player.y = ground - player.height;
121:       player.vy = 0;
122:       player.onGround = true;
123:     }
124: 
125:     const speed = 300 + Math.min(150, elapsed * 2.4);
126:     spawnObstacle -= dt;
127:     if (spawnObstacle <= 0) {
128:       const tall = Math.random() > 0.48;
129:       obstacles.push({ x: W + 22, y: ground - (tall ? 51 : 38), width: tall ? 43 : 54, height: tall ? 51 : 38, tall });
130:       spawnObstacle = Math.max(0.72, 1.42 - elapsed * 0.008) + Math.random() * 0.38;
131:     }
132:     spawnPatch -= dt;
133:     if (spawnPatch <= 0) {
134:       const high = Math.random() > 0.62;
135:       patches.push({ x: W + 24, y: ground - (high ? 119 : 47), width: 27, height: 27, spin: Math.random() * Math.PI });
136:       spawnPatch = 1.05 + Math.random() * 0.6;
137:     }
138: 
139:     obstacles.forEach(obstacle => { obstacle.x -= speed * dt; });
140:     patches.forEach(patch => { patch.x -= speed * dt; patch.spin += dt * 3; });
141:     obstacles = obstacles.filter(obstacle => obstacle.x + obstacle.width > -10);
142:     patches = patches.filter(patch => patch.x + patch.width > -10);
143: 
144:     const body = { x: player.x + 5, y: player.y + 4, width: player.width - 10, height: player.height - 5 };
145:     if (invulnerable <= 0) {
146:       const hit = obstacles.find(obstacle => overlaps(body, obstacle));
147:       if (hit) {
148:         obstacles = obstacles.filter(obstacle => obstacle !== hit);
149:         lives -= 1;
150:         invulnerable = 1.15;
151:         updateHud();
152:         if (lives <= 0) return finishGame(false);
153:       }
154:     }
155:     patches = patches.filter(patch => {
156:       const close = overlaps({ x: body.x - 4, y: body.y - 5, width: body.width + 8, height: body.height + 10 }, patch);
157:       if (close) {
158:         score += 1;
159:         updateHud();
160:         if (score >= 12) finishGame(true);
161:         return false;
162:       }
163:       return true;
164:     });
165:     if (elapsed >= 60) finishGame(false);
166:   }
