168:   function drawBackground() {
169:     const sky = ctx.createLinearGradient(0, 0, 0, H);
170:     sky.addColorStop(0, '#252824');
171:     sky.addColorStop(1, '#47463d');
172:     ctx.fillStyle = sky;
173:     ctx.fillRect(0, 0, W, H);
174:     ctx.fillStyle = '#d6e363';
175:     ctx.beginPath();
176:     ctx.arc(790, 79, 24, 0, Math.PI * 2);
177:     ctx.fill();
178:     ctx.fillStyle = '#252824';
179:     ctx.beginPath();
180:     ctx.arc(800, 70, 23, 0, Math.PI * 2);
181:     ctx.fill();
182: 
183:     skyline.forEach((building, i) => {
184:       const shift = (scenery * (i % 3 === 0 ? 0.15 : 0.08)) % 1080;
185:       let x = building.x - shift;
186:       if (x + building.width < 0) x += 1080;
187:       ctx.fillStyle = i % 3 === 0 ? '#343730' : '#30332e';
188:       ctx.fillRect(x, ground - building.height, building.width, building.height);
189:       ctx.fillStyle = '#777668';
190:       for (let row = 0; row < Math.floor(building.height / 24); row++) {
191:         for (let col = 0; col < 3; col++) {
192:           if ((i + row + col) % 3 !== 0) ctx.fillRect(x + 8 + col * 13, ground - building.height + 13 + row * 22, 4, 7);
193:         }
194:       }
195:     });
196: 
197:     ctx.fillStyle = '#1d1f1b';
198:     ctx.fillRect(0, ground, W, H - ground);
199:     ctx.fillStyle = '#626052';
200:     ctx.fillRect(0, ground, W, 3);
201:     ctx.strokeStyle = '#67675d';
202:     ctx.lineWidth = 2;
203:     ctx.setLineDash([35, 29]);
204:     ctx.lineDashOffset = -scenery % 64;
205:     ctx.beginPath();
206:     ctx.moveTo(0, ground + 43);
207:     ctx.lineTo(W, ground + 43);
208:     ctx.stroke();
209:     ctx.setLineDash([]);
210:     ctx.fillStyle = '#e44d32';
211:     ctx.fillRect(0, ground - 3, 78, 4);
212:   }
213: 
214:   function drawPlayer() {
215:     if (invulnerable > 0 && Math.floor(invulnerable * 12) % 2 === 0) return;
216:     const x = player.x;
217:     const y = player.y;
218:     const step = player.onGround ? Math.sin(player.leg) * 5 : 2;
219:     ctx.save();
220:     ctx.translate(x, y);
221:     // legs and trainers
222:     ctx.strokeStyle = '#d6d3c7';
223:     ctx.lineWidth = 8;
224:     ctx.lineCap = 'round';
225:     ctx.beginPath();
226:     ctx.moveTo(16, 40); ctx.lineTo(15 - step, 53);
227:     ctx.moveTo(27, 40); ctx.lineTo(29 + step, 53);
228:     ctx.stroke();
229:     ctx.strokeStyle = '#e44d32';
230:     ctx.lineWidth = 6;
231:     ctx.beginPath();
232:     ctx.moveTo(15 - step, 54); ctx.lineTo(8 - step, 55);
233:     ctx.moveTo(29 + step, 54); ctx.lineTo(36 + step, 55);
234:     ctx.stroke();
235:     // backpack
236:     ctx.fillStyle = '#d6e363';
237:     ctx.fillRect(3, 17, 10, 21);
238:     ctx.fillStyle = '#e44d32';
239:     ctx.fillRect(10, 17, 23, 25);
240:     ctx.fillStyle = '#f2f0e9';
241:     ctx.fillRect(17, 24, 10, 3);
242:     // head and cap
243:     ctx.fillStyle = '#d59a70';
244:     ctx.beginPath();
245:     ctx.arc(22, 11, 10, 0, Math.PI * 2);
246:     ctx.fill();
247:     ctx.fillStyle = '#d6e363';
248:     ctx.fillRect(10, 1, 24, 5);
249:     ctx.fillRect(27, 5, 10, 3);
250:     ctx.restore();
251:   }
252: 
253:   function drawObstacle(obstacle) {
254:     ctx.fillStyle = obstacle.tall ? '#b8422f' : '#c7a46d';
255:     ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
256:     ctx.strokeStyle = '#211e1a';
257:     ctx.lineWidth = 3;
258:     ctx.strokeRect(obstacle.x + 3, obstacle.y + 3, obstacle.width - 6, obstacle.height - 6);
259:     ctx.beginPath();
260:     ctx.moveTo(obstacle.x + 4, obstacle.y + obstacle.height - 5);
261:     ctx.lineTo(obstacle.x + obstacle.width - 4, obstacle.y + 5);
262:     ctx.moveTo(obstacle.x + 4, obstacle.y + 5);
263:     ctx.lineTo(obstacle.x + obstacle.width - 4, obstacle.y + obstacle.height - 5);
264:     ctx.stroke();
265:   }
266: 
267:   function drawPatch(patch) {
268:     ctx.save();
269:     ctx.translate(patch.x + patch.width / 2, patch.y + patch.height / 2);
270:     ctx.rotate(Math.sin(patch.spin) * 0.18);
271:     ctx.fillStyle = '#d6e363';
272:     ctx.fillRect(-12, -12, 24, 24);
273:     ctx.strokeStyle = '#171816';
274:     ctx.lineWidth = 2;
275:     ctx.strokeRect(-8, -8, 16, 16);
276:     ctx.fillStyle = '#171816';
277:     ctx.font = 'bold 12px monospace';
278:     ctx.textAlign = 'center';
279:     ctx.textBaseline = 'middle';
280:     ctx.fillText('✳', 0, 1);
281:     ctx.restore();
282:   }
283: 
284:   function draw() {
285:     if (!canvas.width || !canvas.height) return;
286:     drawBackground();
287:     patches.forEach(drawPatch);
288:     obstacles.forEach(drawObstacle);
289:     drawPlayer();
290:     ctx.fillStyle = '#f2f0e9';
291:     ctx.font = '10px monospace';
292:     ctx.fillText('SP · 23:98', 20, 27);
293:     ctx.textAlign = 'right';
294:     ctx.fillText('RUA É MOVIMENTO', W - 20, 27);
295:     ctx.textAlign = 'left';
296:   }
297: 
298:   function frame(now) {
299:     const dt = Math.min(0.035, Math.max(0, (now - lastFrame) / 1000));
300:     lastFrame = now;
301:     update(dt);
302:     draw();
303:     requestAnimationFrame(frame);
304:   }
