306:   function keyControl(event, pressed) {
307:     const key = event.key.toLowerCase();
308:     if (['arrowleft', 'a', 'arrowright', 'd', 'arrowup', 'w', ' '].includes(key)) event.preventDefault();
309:     if (key === 'arrowleft' || key === 'a') held.left = pressed;
310:     if (key === 'arrowright' || key === 'd') held.right = pressed;
311:     if (pressed && (key === 'arrowup' || key === 'w' || key === ' ')) jump();
312:     if (pressed && key === 'enter' && state !== 'playing') startGame();
313:   }
314: 
315:   document.addEventListener('keydown', event => keyControl(event, true));
316:   document.addEventListener('keyup', event => keyControl(event, false));
317:   window.addEventListener('blur', () => { held.left = false; held.right = false; });
318:   document.addEventListener('visibilitychange', () => { lastFrame = performance.now(); });
319:   startButton.addEventListener('click', startGame);
320:   resetButton.addEventListener('click', startGame);
321:   document.querySelectorAll('.game-controls button').forEach(button => {
322:     const control = button.dataset.control;
323:     const press = event => {
324:       event.preventDefault();
325:       button.classList.add('is-pressed');
326:       if (control === 'jump') jump();
327:       else held[control] = true;
328:       if (button.setPointerCapture && event.pointerId !== undefined) button.setPointerCapture(event.pointerId);
329:     };
330:     const release = event => {
331:       if (event) event.preventDefault();
332:       button.classList.remove('is-pressed');
333:       if (control !== 'jump') held[control] = false;
334:     };
335:     button.addEventListener('pointerdown', press);
336:     button.addEventListener('pointerup', release);
337:     button.addEventListener('pointercancel', release);
338:     button.addEventListener('lostpointercapture', release);
339:     button.addEventListener('contextmenu', event => event.preventDefault());
340:   });
341: 
342:   if ('ResizeObserver' in window) new ResizeObserver(resizeCanvas).observe(canvas);
343:   else window.addEventListener('resize', resizeCanvas);
344:   resizeCanvas();
345:   updateHud();
346:   lastFrame = performance.now();
347:   requestAnimationFrame(frame);
348: })();
